-- 4. Native Control Hierarchy (GuiRoot, CreateControl)
local function CreateControlMock(name, parent, controlType)
    local ctrl = {
        _name = name,
        _parent = parent,
        _type = controlType or CT_CONTROL,
        _hidden = false,
        _width = 100,
        _height = 100,
        _alpha = 1.0,
        _drawLayer = DL_CONTROLS,
        _drawLevel = 0,
        _text = "",
        _font = "",
        _texture = "",
        _anchors = {},
        _handlers = {},
        _children = {},
        _mouseEnabled = true,
    }

    function ctrl:GetName() return self._name end
    function ctrl:GetType() return self._type end
    function ctrl:SetHidden(hidden) self._hidden = not not hidden end
    function ctrl:IsHidden() return self._hidden end
    function ctrl:SetDimensions(w, h) self._width = w; self._height = h end
    function ctrl:GetDimensions() return self._width, self._height end
    function ctrl:GetWidth() return self._width end
    function ctrl:GetHeight() return self._height end
    function ctrl:SetWidth(w) self._width = w end
    function ctrl:SetHeight(h) self._height = h end
    function ctrl:SetAlpha(alpha) self._alpha = alpha end
    function ctrl:GetAlpha() return self._alpha end
    function ctrl:SetDrawLayer(layer) self._drawLayer = layer end
    function ctrl:GetDrawLayer() return self._drawLayer end
    function ctrl:SetDrawLevel(level) self._drawLevel = level end
    function ctrl:GetDrawLevel() return self._drawLevel end
    function ctrl:SetColor(r, g, b, a) self._color = {r=r, g=g, b=b, a=a} end
    function ctrl:GetColor()
        return self._color and self._color.r or 1,
               self._color and self._color.g or 1,
               self._color and self._color.b or 1,
               self._color and self._color.a or 1
    end
    function ctrl:SetText(t) self._text = tostring(t or "") end
    function ctrl:GetText() return self._text end
    function ctrl:SetFont(f) self._font = f end
    function ctrl:GetFont() return self._font end
    function ctrl:SetHorizontalAlignment(align) self._horizontalAlignment = align end
    function ctrl:GetHorizontalAlignment() return self._horizontalAlignment end
    function ctrl:SetVerticalAlignment(align) self._verticalAlignment = align end
    function ctrl:GetVerticalAlignment() return self._verticalAlignment end
    function ctrl:SetMaxLineCount(maxLines) self._maxLineCount = maxLines end
    function ctrl:GetMaxLineCount() return self._maxLineCount end
    function ctrl:SetWrapMode(mode) self._wrapMode = mode end
    function ctrl:GetWrapMode() return self._wrapMode end
    function ctrl:SetTexture(tex) self._texture = tex end
    function ctrl:GetTextureFileName() return self._texture end
    function ctrl:SetAnchor(point, relTo, relPoint, x, y)
        table.insert(self._anchors, { point = point, relTo = relTo, relPoint = relPoint, x = x or 0, y = y or 0 })
    end
    function ctrl:ClearAnchors() self._anchors = {} end
    function ctrl:GetNumAnchors() return #self._anchors end
    function ctrl:GetAnchor(i)
        local a = self._anchors[i or 1]
        if a then return true, a.point, a.relTo, a.relPoint, a.x, a.y end
        return false
    end
    if controlType == CT_EDITBOX then
        ctrl._topLineIndex = 1
        ctrl._scrollExtents = 0
        function ctrl:GetTopLineIndex() return self._topLineIndex end
        function ctrl:SetTopLineIndex(idx) self._topLineIndex = idx end
        function ctrl:GetScrollExtents() return self._scrollExtents end
    end
    function ctrl:SetHandler(eventName, handler) self._handlers[eventName] = handler end
    function ctrl:GetHandler(eventName) return self._handlers[eventName] end
    function ctrl:FireHandler(eventName, ...)
        if eventName == "OnClicked" and self._enabled == false then
            return
        end
        if self._handlers[eventName] then
            return self._handlers[eventName](self, ...)
        end
    end
    function ctrl:SetEnabled(enabled) self._enabled = (enabled ~= false) end
    function ctrl:IsEnabled() return self._enabled ~= false end
    function ctrl:SetMouseEnabled(enabled) self._mouseEnabled = not not enabled end
    function ctrl:IsMouseEnabled() return self._mouseEnabled end
    function ctrl:GetParent() return self._parent end
    function ctrl:SetParent(p) self._parent = p end
    function ctrl:AddChild(c) table.insert(self._children, c) end
    function ctrl:GetNumChildren() return #self._children end
    function ctrl:GetChild(i) return self._children[i] end

    if name and name ~= "" then
        _G[name] = ctrl
    end
    if parent and parent.AddChild then
        parent:AddChild(ctrl)
    end
    return ctrl
end

