-- 6. Interface Managers (SCENE_MANAGER, MAIN_MENU_KEYBOARD, SYSTEMS)
local SceneManagerClass = ZO_CallbackObject:Subclass()
function SceneManagerClass:Initialize()
    ZO_CallbackObject.Initialize(self)
    self.scenes = {}
    self.currentScene = nil
end
function SceneManagerClass:AddScene(scene)
    self.scenes[scene:GetName()] = scene
end
function SceneManagerClass:GetScene(name)
    return self.scenes[name]
end
function SceneManagerClass:Show(name)
    local scene = self.scenes[name]
    if not scene then
        scene = ZO_Scene:New(name, self)
        self:AddScene(scene)
    end
    if self.currentScene and self.currentScene ~= scene then
        self.currentScene.state = SCENE_HIDDEN
        for _, f in ipairs(self.currentScene.fragments) do
            f._sceneShowing = false
            f:Hide()
        end
        self.currentScene:FireCallbacks("StateChange", SCENE_SHOWN, SCENE_HIDDEN)
    end
    self.currentScene = scene
    scene.state = SCENE_SHOWN
    for _, f in ipairs(scene.fragments) do
        f._sceneShowing = true
        f:Show()
    end
    scene:FireCallbacks("StateChange", SCENE_HIDDEN, SCENE_SHOWN)
    self:FireCallbacks("SceneStateChange", scene, SCENE_HIDDEN, SCENE_SHOWN)
end
function SceneManagerClass:Hide(name)
    local scene = self.scenes[name] or self.currentScene
    if scene then
        scene.state = SCENE_HIDDEN
        for _, f in ipairs(scene.fragments) do f:Hide() end
        scene:FireCallbacks("StateChange", SCENE_SHOWN, SCENE_HIDDEN)
        self:FireCallbacks("SceneStateChange", scene, SCENE_SHOWN, SCENE_HIDDEN)
    end
    if self.currentScene == scene then
        self.currentScene = nil
    end
end
function SceneManagerClass:Toggle(name)
    if self:IsShowing(name) then
        self:Hide(name)
    else
        self:Show(name)
    end
end
function SceneManagerClass:GetCurrentScene() return self.currentScene end
function SceneManagerClass:GetCurrentSceneName() return self.currentScene and self.currentScene:GetName() or "" end
function SceneManagerClass:IsShowing(name)
    if not name then return self.currentScene ~= nil end
    local s = self.scenes[name]
    return s and s:IsShowing() or false
end

